3813|md_analyze_dollar(MD_CTX* ctx, int mark_index)
3814|{
3815|    MD_MARK* mark = &ctx->marks[mark_index];
3816|
3817|    if((mark->flags & MD_MARK_POTENTIAL_CLOSER)  &&  DOLLAR_OPENERS.top >= 0) {
3818|        /* If the potential closer has a non-matching number of $, discard */
3819|        MD_MARK* opener = &ctx->marks[DOLLAR_OPENERS.top];
3820|        int opener_index = DOLLAR_OPENERS.top;
3821|        MD_MARK* closer = mark;
3822|        int closer_index = mark_index;
3823|
3824|        if(opener->end - opener->beg == closer->end - closer->beg) {
3825|            /* We are the matching closer */
3826|            md_pop_openers(ctx, opener_index);
3827|            md_disable_marks(ctx, opener_index+1, closer_index);
3828|            md_resolve_range(ctx, opener_index, closer_index);
3829|
3830|            /* Discard all pending openers: Latex math span do not allow
3831|             * nesting. */
3832|            DOLLAR_OPENERS.top = -1;
3833|            return;
3834|        }
3835|    }
3836|
3837|    if(mark->flags & MD_MARK_POTENTIAL_OPENER)
3838|        md_mark_stack_push(ctx, &DOLLAR_OPENERS, mark_index);
