6477|
6478|    if(parser->abi_version != 0) {
6479|        if(parser->debug_log != NULL)
6480|            parser->debug_log("Unsupported abi_version.", userdata);
6481|        return -1;
6482|    }
6483|
6484|    /* Setup context structure. */
6485|    memset(&ctx, 0, sizeof(MD_CTX));
6486|    ctx.text = text;
6487|    ctx.size = size;
6488|    memcpy(&ctx.parser, parser, sizeof(MD_PARSER));
6489|    ctx.userdata = userdata;
6490|    ctx.code_indent_offset = (ctx.parser.flags & MD_FLAG_NOINDENTEDCODEBLOCKS) ? (OFF)(-1) : 4;
6491|    md_build_mark_char_map(&ctx);
6492|    ctx.doc_ends_with_newline = (size > 0  &&  ISNEWLINE_(text[size-1]));
6493|    ctx.max_ref_def_output = 16 * MIN(size, (MD_SIZE)(1024 * 1024 / 16));
6494|
6495|    /* Reset all mark stacks and lists. */
6496|    for(i = 0; i < (int) SIZEOF_ARRAY(ctx.opener_stacks); i++)
6497|        ctx.opener_stacks[i].top = -1;
6498|    ctx.ptr_stack.top = -1;
6499|    ctx.unresolved_link_head = -1;
6500|    ctx.unresolved_link_tail = -1;
6501|    ctx.table_cell_boundaries_head = -1;
6502|    ctx.table_cell_boundaries_tail = -1;
6503|
6504|    /* All the work. */
6505|    ret = md_process_doc(&ctx);
6506|
6507|    /* Clean-up. */
6508|    md_free_ref_defs(&ctx);
6509|    md_free_ref_def_hashtable(&ctx);
