269|static void
270|render_open_ol_block(MD_HTML* r, const MD_BLOCK_OL_DETAIL* det)
271|{
272|    char buf[64];
273|
274|    if(det->start == 1) {
275|        RENDER_VERBATIM(r, "<ol>\n");
276|        return;
277|    }
278|
279|    snprintf(buf, sizeof(buf), "<ol start=\"%u\">\n", det->start);
280|    RENDER_VERBATIM(r, buf);
