283|static void
284|render_open_li_block(MD_HTML* r, const MD_BLOCK_LI_DETAIL* det)
285|{
286|    if(det->is_task) {
287|        RENDER_VERBATIM(r, "<li class=\"task-list-item\">"
288|                          "<input type=\"checkbox\" class=\"task-list-item-checkbox\" disabled");
289|        if(r->flags & MD_HTML_FLAG_XHTML) RENDER_VERBATIM(r, "=\"true\"");
290|        if(det->task_mark == 'x' || det->task_mark == 'X') {
291|            RENDER_VERBATIM(r, " checked");
292|            if(r->flags & MD_HTML_FLAG_XHTML) RENDER_VERBATIM(r, "=\"true\"");
293|        }
294|        RENDER_VERBATIM(r, (r->flags & MD_HTML_FLAG_XHTML) ? " />" : ">");
295|    } else {
296|        RENDER_VERBATIM(r, "<li>");
297|    }
298|}
