300|static void
301|render_open_code_block(MD_HTML* r, const MD_BLOCK_CODE_DETAIL* det)
302|{
303|    RENDER_VERBATIM(r, "<pre><code");
304|
305|    /* If known, output the HTML 5 attribute class="language-LANGNAME". */
306|    if(det->lang.text != NULL) {
307|        RENDER_VERBATIM(r, " class=\"");
308|        if(det->lang.size < 9  ||  strncmp(det->lang.text, "language-", 9) != 0) {
309|            RENDER_VERBATIM(r, "language-");
310|        }
311|        render_attribute(r, &det->lang, render_html_escaped);
312|        RENDER_VERBATIM(r, "\"");
313|    }
314|
315|    RENDER_VERBATIM(r, ">");
316|}
