318|static void
319|render_open_td_block(MD_HTML* r, const MD_CHAR* cell_type, const MD_BLOCK_TD_DETAIL* det)
320|{
321|    RENDER_VERBATIM(r, "<");
322|    RENDER_VERBATIM(r, cell_type);
323|
324|    switch(det->align) {
325|        case MD_ALIGN_LEFT:     RENDER_VERBATIM(r, " align=\"left\">"); break;
326|        case MD_ALIGN_CENTER:   RENDER_VERBATIM(r, " align=\"center\">"); break;
327|        case MD_ALIGN_RIGHT:    RENDER_VERBATIM(r, " align=\"right\">"); break;
328|        default:                RENDER_VERBATIM(r, ">"); break;
329|    }
