332|static void
333|render_open_a_span(MD_HTML* r, const MD_SPAN_A_DETAIL* det)
334|{
335|    RENDER_VERBATIM(r, "<a href=\"");
336|    render_attribute(r, &det->href, render_url_escaped);
337|
338|    if(det->title.text != NULL) {
339|        RENDER_VERBATIM(r, "\" title=\"");
340|        render_attribute(r, &det->title, render_html_escaped);
341|    }
342|
343|    RENDER_VERBATIM(r, "\">");
