380|static int
381|enter_block_callback(MD_BLOCKTYPE type, void* detail, void* userdata)
382|{
383|    static const MD_CHAR* head[6] = { "<h1>", "<h2>", "<h3>", "<h4>", "<h5>", "<h6>" };
384|    MD_HTML* r = (MD_HTML*) userdata;
385|
386|    switch(type) {
387|        case MD_BLOCK_DOC:      /* noop */ break;
388|        case MD_BLOCK_QUOTE:    RENDER_VERBATIM(r, "<blockquote>\n"); break;
389|        case MD_BLOCK_UL:       RENDER_VERBATIM(r, "<ul>\n"); break;
390|        case MD_BLOCK_OL:       render_open_ol_block(r, (const MD_BLOCK_OL_DETAIL*)detail); break;
391|        case MD_BLOCK_LI:       render_open_li_block(r, (const MD_BLOCK_LI_DETAIL*)detail); break;
392|        case MD_BLOCK_HR:       RENDER_VERBATIM(r, (r->flags & MD_HTML_FLAG_XHTML) ? "<hr />\n" : "<hr>\n"); break;
393|        case MD_BLOCK_H:        RENDER_VERBATIM(r, head[((MD_BLOCK_H_DETAIL*)detail)->level - 1]); break;
394|        case MD_BLOCK_CODE:     render_open_code_block(r, (const MD_BLOCK_CODE_DETAIL*) detail); break;
395|        case MD_BLOCK_HTML:     /* noop */ break;
396|        case MD_BLOCK_P:        RENDER_VERBATIM(r, "<p>"); break;
397|        case MD_BLOCK_TABLE:    RENDER_VERBATIM(r, "<table>\n"); break;
398|        case MD_BLOCK_THEAD:    RENDER_VERBATIM(r, "<thead>\n"); break;
399|        case MD_BLOCK_TBODY:    RENDER_VERBATIM(r, "<tbody>\n"); break;
400|        case MD_BLOCK_TR:       RENDER_VERBATIM(r, "<tr>\n"); break;
401|        case MD_BLOCK_TH:       render_open_td_block(r, "th", (MD_BLOCK_TD_DETAIL*)detail); break;
402|        case MD_BLOCK_TD:       render_open_td_block(r, "td", (MD_BLOCK_TD_DETAIL*)detail); break;
403|    }
404|
405|    return 0;
406|}
