408|static int
409|leave_block_callback(MD_BLOCKTYPE type, void* detail, void* userdata)
410|{
411|    static const MD_CHAR* head[6] = { "</h1>\n", "</h2>\n", "</h3>\n", "</h4>\n", "</h5>\n", "</h6>\n" };
412|    MD_HTML* r = (MD_HTML*) userdata;
413|
414|    switch(type) {
415|        case MD_BLOCK_DOC:      /*noop*/ break;
416|        case MD_BLOCK_QUOTE:    RENDER_VERBATIM(r, "</blockquote>\n"); break;
417|        case MD_BLOCK_UL:       RENDER_VERBATIM(r, "</ul>\n"); break;
418|        case MD_BLOCK_OL:       RENDER_VERBATIM(r, "</ol>\n"); break;
419|        case MD_BLOCK_LI:       RENDER_VERBATIM(r, "</li>\n"); break;
420|        case MD_BLOCK_HR:       /*noop*/ break;
421|        case MD_BLOCK_H:        RENDER_VERBATIM(r, head[((MD_BLOCK_H_DETAIL*)detail)->level - 1]); break;
422|        case MD_BLOCK_CODE:     RENDER_VERBATIM(r, "</code></pre>\n"); break;
423|        case MD_BLOCK_HTML:     /* noop */ break;
424|        case MD_BLOCK_P:        RENDER_VERBATIM(r, "</p>\n"); break;
425|        case MD_BLOCK_TABLE:    RENDER_VERBATIM(r, "</table>\n"); break;
426|        case MD_BLOCK_THEAD:    RENDER_VERBATIM(r, "</thead>\n"); break;
427|        case MD_BLOCK_TBODY:    RENDER_VERBATIM(r, "</tbody>\n"); break;
428|        case MD_BLOCK_TR:       RENDER_VERBATIM(r, "</tr>\n"); break;
429|        case MD_BLOCK_TH:       RENDER_VERBATIM(r, "</th>\n"); break;
430|        case MD_BLOCK_TD:       RENDER_VERBATIM(r, "</td>\n"); break;
431|    }
432|
433|    return 0;
