435|
436|static int
437|enter_span_callback(MD_SPANTYPE type, void* detail, void* userdata)
438|{
439|    MD_HTML* r = (MD_HTML*) userdata;
440|    int inside_img = (r->image_nesting_level > 0);
441|
442|    /* We are inside a Markdown image label. Markdown allows to use any emphasis
443|     * and other rich contents in that context similarly as in any link label.
444|     *
445|     * However, unlike in the case of links (where that contents becomescontents
446|     * of the <a>...</a> tag), in the case of images the contents is supposed to
447|     * fall into the attribute alt: <img alt="...">.
448|     *
449|     * In that context we naturally cannot output nested HTML tags. So lets
450|     * suppress them and only output the plain text (i.e. what falls into text()
451|     * callback).
452|     *
453|     * CommonMark specification declares this a recommended practice for HTML
454|     * output.
455|     */
456|    if(type == MD_SPAN_IMG)
457|        r->image_nesting_level++;
458|    if(inside_img)
459|        return 0;
460|
461|    switch(type) {
462|        case MD_SPAN_EM:                RENDER_VERBATIM(r, "<em>"); break;
463|        case MD_SPAN_STRONG:            RENDER_VERBATIM(r, "<strong>"); break;
464|        case MD_SPAN_U:                 RENDER_VERBATIM(r, "<u>"); break;
465|        case MD_SPAN_A:                 render_open_a_span(r, (MD_SPAN_A_DETAIL*) detail); break;
466|        case MD_SPAN_IMG:               render_open_img_span(r, (MD_SPAN_IMG_DETAIL*) detail); break;
467|        case MD_SPAN_CODE:              RENDER_VERBATIM(r, "<code>"); break;
468|        case MD_SPAN_DEL:               RENDER_VERBATIM(r, "<del>"); break;
469|        case MD_SPAN_LATEXMATH:         RENDER_VERBATIM(r, "<x-equation>"); break;
470|        case MD_SPAN_LATEXMATH_DISPLAY: RENDER_VERBATIM(r, "<x-equation type=\"display\">"); break;
471|        case MD_SPAN_WIKILINK:          render_open_wikilink_span(r, (MD_SPAN_WIKILINK_DETAIL*) detail); break;
472|    }
473|
474|    return 0;
475|}
476|
477|static int
478|leave_span_callback(MD_SPANTYPE type, void* detail, void* userdata)
479|{
480|    MD_HTML* r = (MD_HTML*) userdata;
481|
482|    if(type == MD_SPAN_IMG)
483|        r->image_nesting_level--;
484|    if(r->image_nesting_level > 0)
485|        return 0;
486|
487|    switch(type) {
488|        case MD_SPAN_EM:                RENDER_VERBATIM(r, "</em>"); break;
489|        case MD_SPAN_STRONG:            RENDER_VERBATIM(r, "</strong>"); break;
490|        case MD_SPAN_U:                 RENDER_VERBATIM(r, "</u>"); break;
491|        case MD_SPAN_A:                 RENDER_VERBATIM(r, "</a>"); break;
492|        case MD_SPAN_IMG:               render_close_img_span(r, (MD_SPAN_IMG_DETAIL*) detail); break;
493|        case MD_SPAN_CODE:              RENDER_VERBATIM(r, "</code>"); break;
494|        case MD_SPAN_DEL:               RENDER_VERBATIM(r, "</del>"); break;
495|        case MD_SPAN_LATEXMATH:         /*fall through*/
496|        case MD_SPAN_LATEXMATH_DISPLAY: RENDER_VERBATIM(r, "</x-equation>"); break;
497|        case MD_SPAN_WIKILINK:          RENDER_VERBATIM(r, "</x-wikilink>"); break;
498|    }
499|
500|    return 0;
501|}
502|
503|static int
504|text_callback(MD_TEXTTYPE type, const MD_CHAR* text, MD_SIZE size, void* userdata)
505|{
506|    MD_HTML* r = (MD_HTML*) userdata;
507|
508|    switch(type) {
509|        case MD_TEXT_NULLCHAR:  render_utf8_codepoint(r, 0x0000, render_verbatim); break;
510|        case MD_TEXT_BR:        RENDER_VERBATIM(r, (r->image_nesting_level == 0
511|                                        ? ((r->flags & MD_HTML_FLAG_XHTML) ? "<br />\n" : "<br>\n")
512|                                        : " "));
513|                                break;
514|        case MD_TEXT_SOFTBR:    RENDER_VERBATIM(r, (r->image_nesting_level == 0 ? "\n" : " ")); break;
515|        case MD_TEXT_HTML:      render_verbatim(r, text, size); break;
516|        case MD_TEXT_ENTITY:    render_entity(r, text, size, render_html_escaped); break;
517|        default:                render_html_escaped(r, text, size); break;
518|    }
519|
520|    return 0;
521|}
