524|debug_log_callback(const char* msg, void* userdata)
525|{
526|    MD_HTML* r = (MD_HTML*) userdata;
527|    if(r->flags & MD_HTML_FLAG_DEBUG)
528|        fprintf(stderr, "MD4C: %s\n", msg);
