436|static int
437|enter_span_callback(MD_SPANTYPE type, void* detail, void* userdata)
438|{
439|    MD_HTML* r = (MD_HTML*) userdata;
440|    int inside_img = (r->image_nesting_level > 0);
441|
442|    /* We are inside a Markdown image label. Markdown allows to use any emphasis
443|     * and other rich contents in that context similarly as in any link label.
444|     *
445|     * However, unlike in the case of links (where that contents becomescontents
446|     * of the <a>...</a> tag), in the case of images the contents is supposed to
447|     * fall into the attribute alt: <img alt="...">.
448|     *
449|     * In that context we naturally cannot output nested HTML tags. So lets
450|     * suppress them and only output the plain text (i.e. what falls into text()
451|     * callback).
452|     *
453|     * CommonMark specification declares this a recommended practice for HTML
454|     * output.
455|     */
456|    if(type == MD_SPAN_IMG)
457|        r->image_nesting_level++;
458|    if(inside_img)
459|        return 0;
460|
461|    switch(type) {
462|        case MD_SPAN_EM:                RENDER_VERBATIM(r, "<em>"); break;
463|        case MD_SPAN_STRONG:            RENDER_VERBATIM(r, "<strong>"); break;
464|        case MD_SPAN_U:                 RENDER_VERBATIM(r, "<u>"); break;
465|        case MD_SPAN_A:                 render_open_a_span(r, (MD_SPAN_A_DETAIL*) detail); break;
466|        case MD_SPAN_IMG:               render_open_img_span(r, (MD_SPAN_IMG_DETAIL*) detail); break;
467|        case MD_SPAN_CODE:              RENDER_VERBATIM(r, "<code>"); break;
468|        case MD_SPAN_DEL:               RENDER_VERBATIM(r, "<del>"); break;
469|        case MD_SPAN_SPOILER:           RENDER_VERBATIM(r, "<x-spoiler>"); break;
470|        case MD_SPAN_LATEXMATH:         RENDER_VERBATIM(r, "<x-equation>"); break;
471|        case MD_SPAN_LATEXMATH_DISPLAY: RENDER_VERBATIM(r, "<x-equation type=\"display\">"); break;
472|        case MD_SPAN_WIKILINK:          render_open_wikilink_span(r, (MD_SPAN_WIKILINK_DETAIL*) detail); break;
473|    }
474|
475|    return 0;
476|}
477|
478|static int
479|leave_span_callback(MD_SPANTYPE type, void* detail, void* userdata)
480|{
481|    MD_HTML* r = (MD_HTML*) userdata;
482|
483|    if(type == MD_SPAN_IMG)
484|        r->image_nesting_level--;
485|    if(r->image_nesting_level > 0)
486|        return 0;
487|
488|    switch(type) {
489|        case MD_SPAN_EM:                RENDER_VERBATIM(r, "</em>"); break;
490|        case MD_SPAN_STRONG:            RENDER_VERBATIM(r, "</strong>"); break;
491|        case MD_SPAN_U:                 RENDER_VERBATIM(r, "</u>"); break;
492|        case MD_SPAN_A:                 RENDER_VERBATIM(r, "</a>"); break;
493|        case MD_SPAN_IMG:               render_close_img_span(r, (MD_SPAN_IMG_DETAIL*) detail); break;
494|        case MD_SPAN_CODE:              RENDER_VERBATIM(r, "</code>"); break;
495|        case MD_SPAN_DEL:               RENDER_VERBATIM(r, "</del>"); break;
496|        case MD_SPAN_SPOILER:           RENDER_VERBATIM(r, "</x-spoiler>"); break;
497|        case MD_SPAN_LATEXMATH:         /*fall through*/
498|        case MD_SPAN_LATEXMATH_DISPLAY: RENDER_VERBATIM(r, "</x-equation>"); break;
499|        case MD_SPAN_WIKILINK:          RENDER_VERBATIM(r, "</x-wikilink>"); break;
500|    }
501|
502|    return 0;
503|}
